log_analytics_workspace_timeouts.tfType:
object({
    create = optional(string)
    delete = optional(string)
    read   = optional(string)
    update = optional(string)
  })

network_security_perimeter_association.tfType:
object({
    resource_id  = string
    profile_name = string
    access_mode  = optional(string, "Learning")
  })

log_analytics_workspace_tables_update.tfType:
map(object({
    name                    = string
    resource_id             = optional(string)
    retention_in_days       = optional(number)
    total_retention_in_days = optional(number)
    plan                    = optional(string)
    schema = optional(object({
      name        = optional(string)
      description = optional(string)
      columns = optional(list(object({
        name = string
        type = string
      })), [])
    }))
  }))

monitor_private_link_scoped_resource.tfType:
map(object({
    name        = optional(string)
    resource_id = string
    exclusions = optional(list(object({
      ingestion_access_mode            = optional(string, "PrivateOnly")
      query_access_mode                = optional(string, "PrivateOnly")
      private_endpoint_connection_name = string
    })), [])
  }))

lock.tfType:
object({
    kind = string
    name = optional(string, null)
  })

monitor_private_link_scope.tfType:
map(object({
    name                  = optional(string)
    resource_id           = string
    ingestion_access_mode = optional(string, "PrivateOnly")
    query_access_mode     = optional(string, "PrivateOnly")
    exclusions = optional(list(object({
      ingestion_access_mode            = optional(string, "PrivateOnly")
      query_access_mode                = optional(string, "PrivateOnly")
      private_endpoint_connection_name = string
    })), [])
    lock = optional(object({
      kind = string
      name = optional(string, null)
    }))
  }))

private_endpoint_extensions.tfType:
map(object({
    monitor_private_link_scope_key = optional(string, null)
    monitor_private_link_scope_exclusion = optional(object({
      exclude               = optional(bool, true)
      ingestion_access_mode = optional(string, "PrivateOnly")
      query_access_mode     = optional(string, "PrivateOnly")
    }), null)
    manage_dns_zone_group = optional(bool, true)
  }))

log_analytics_workspace_tables.tfType:
map(object({
    name                    = string
    resource_id             = optional(string)
    retention_in_days       = optional(number)
    total_retention_in_days = optional(number)
    plan                    = optional(string)
    schema = optional(object({
      name        = optional(string)
      description = optional(string)
      columns = optional(list(object({
        name = string
        type = string
      })), [])
    }))
  }))
